// Copy the existing binary item
const item = $input.item;

if (item.binary && item.binary.data) {
  // Change the extension so the Compression node accepts it
  item.binary.data.fileName = 'archive.zip';
  item.binary.data.fileExtension = 'zip';
  item.binary.data.mimeType = 'application/zip';
}

return item;

const outputItems = [];

for (const item of $input.all()) {
  const binaryData = item.binary || {};

  for (const [key, file] of Object.entries(binaryData)) {
    const fileName = (file.fileName || '').toLowerCase();

    if (fileName.endsWith('.html') || fileName.endsWith('.xhtml') || fileName.endsWith('.htm')) {
      const buffer = await this.helpers.getBinaryDataBuffer(0, key);
      const rawHtml = buffer.toString('utf8');

      // Grab inner body content
      const bodyMatch = rawHtml.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
      const content = bodyMatch ? bodyMatch[1] : rawHtml;

      const cleanText = content
        .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
        .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
        // Turn paragraph, heading, div, and line-break tags into newlines
        .replace(/<\/(p|div|h[1-6]|li|blockquote)>/gi, '\n\n')
        .replace(/<br\s*\/?>/gi, '\n')
        // Strip all remaining inline HTML tags (like <em>, <strong>, <span>)
        .replace(/<[^>]+>/g, '')
        // Decode common HTML entities
        .replace(/&nbsp;/g, ' ')
        .replace(/&amp;/g, '&')
        .replace(/&lt;/g, '<')
        .replace(/&gt;/g, '>')
        .replace(/&quot;/g, '"')
        .replace(/&#39;|&apos;/g, "'")
        // Clean up excessive spaces on each line while keeping paragraph breaks
        .replace(/[ \t]+/g, ' ')
        .replace(/\n\s*\n+/g, '\n\n')
        .trim();

      outputItems.push({
        json: {
          originalFileName: file.fileName,
          text: cleanText
        }
      });
    }
  }
}

outputItems.sort((a, b) => a.json.originalFileName.localeCompare(b.json.originalFileName));

return outputItems;
